/**
 * @module tests/e2e/feature_file_parity_test
 *
 * Existing Cucumber projects (epic #915, Case B, constraint 1): a `.feature`
 * file with no `# [ID]` header must change nothing. The snapshots in
 * `__snapshots__/feature_file_parity_test.ts.snap` were generated by running
 * this file against a `git archive origin/main` checkout, before the
 * `.feature` extractor existed, and must pass unchanged on the feature
 * branch. Do not regenerate them from the feature branch.
 */

import { assertEquals, assertFalse } from "@std/assert";
import { assertSnapshot } from "@std/testing/snapshot";
import { join } from "@std/path";
import { markspecInDir, markspecPersist } from "./helpers.ts";

const LOCK_PERMISSIONS = ["--allow-net", "--allow-env", "--allow-run"];

const STK = `# Stakeholder requirements

- [STK_BRK_0001] Stop the vehicle

  The vehicle shall stop when the driver brakes.

      Id: 01HGW2Q8MNP3RSTVWXYZABCDEF
`;

const SRS = `# Software requirements

- [SRS_BRK_0001] Brake command

  The controller shall send the brake command within 200 ms.

      Id: 01HGW2Q8MNP3RSTVWXYZABCDEG
      Satisfies: STK_BRK_0001
`;

/** Realistic headerless Cucumber files: Background, Outline, tags, comments. */
const LOGIN_FEATURE = `# language: en
@auth @smoke
Feature: Login

  # TODO: add the lockout scenarios
  Background:
    Given a registered user "alice"

  @happy
  Scenario: Successful login
    When she logs in with the right password
    Then she sees her dashboard

  # Not a header: no bracketed display ID here.
  Scenario Outline: Failed login
    When she logs in with the password "<password>"
    Then she sees the error "<error>"

    Examples:
      | password | error             |
      | wrong    | Invalid password  |
      |          | Password required |
`;

const CHECKOUT_FEATURE = `Feature: Checkout
  As a shopper I want to pay

  Rule: Payment
    Scenario: Pay by card
      Given a basket with 2 items
      When the shopper pays by card
      Then the order is confirmed

    Scenario: Pay with a bracketed word [draft] in the name
      Given an empty basket
      Then the pay button is disabled
`;

const BROKEN_FEATURE = `Feature: Broken
  Scenario Outline: never closed
    Given <a
  Examples:
    | x |
  Rule Without Colon
`;

const FILES: Record<string, string> = {
  "project.yaml": "name: shop\nversion: 0.1.0\n",
  ".markspec.yaml": "profiles: []\n",
  "docs/stk.md": STK,
  "docs/srs.md": SRS,
  "features/login.feature": LOGIN_FEATURE,
  "features/checkout.feature": CHECKOUT_FEATURE,
  "features/broken.feature": BROKEN_FEATURE,
};

const COMPILE_ARGS = [
  "compile",
  "--format",
  "json",
  "docs/stk.md",
  "docs/srs.md",
  "features/login.feature",
  "features/checkout.feature",
  "features/broken.feature",
];

/** Replace the temporary directory, which differs between runs. */
const norm = (text: string, dir: string): string =>
  text.replaceAll(Deno.realPathSync(dir), "<dir>").replaceAll(dir, "<dir>")
    .replace(/"mtime": "[^"]*"/g, '"mtime": "<mtime>"')
    // The bare-check scope line counts discovered `.feature` files;
    // accepted wording change (decision on #915).
    .split("\n").filter((l) => !l.includes("file(s) under")).join("\n");

/** Remove the lines that differ between runs. */
const stableLock = (lock: string): string =>
  lock.split("\n").filter((l) => !l.startsWith("locked-at")).join("\n");

Deno.test("headerless .feature: compile --format json is unchanged", async (t) => {
  const run = await markspecPersist(COMPILE_ARGS, { files: FILES });
  try {
    await assertSnapshot(t, {
      code: run.code,
      stdout: norm(run.stdout, run.dir),
    });
    await assertSnapshot(t, norm(run.stderr, run.dir), {
      name: "compile stderr",
    });
  } finally {
    await Deno.remove(run.dir, { recursive: true });
  }
});

Deno.test("headerless .feature: check --format json is unchanged", async (t) => {
  const run = await markspecPersist(["check", "--format", "json"], {
    files: FILES,
  });
  try {
    await assertSnapshot(t, {
      code: run.code,
      stdout: norm(run.stdout, run.dir),
    });
    await assertSnapshot(t, norm(run.stderr, run.dir), {
      name: "check stderr",
    });
  } finally {
    await Deno.remove(run.dir, { recursive: true });
  }
});

Deno.test("headerless .feature: markspec.lock is unchanged and check reports no drift", async (t) => {
  const run = await markspecPersist(["lock"], {
    files: FILES,
    permissions: LOCK_PERMISSIONS,
  });
  try {
    assertEquals(run.code, 0, run.stderr);
    const lock = await Deno.readTextFile(join(run.dir, "markspec.lock"));
    await assertSnapshot(t, stableLock(lock));
    const check = await markspecInDir(run.dir, ["check"], LOCK_PERMISSIONS);
    assertFalse(check.stderr.includes("MSL-L212"), check.stderr);
    await assertSnapshot(t, {
      code: check.code,
      stderr: norm(check.stderr, run.dir),
    }, {
      name: "check after lock",
    });
  } finally {
    await Deno.remove(run.dir, { recursive: true });
  }
});
